import{_ as e,a as r,b as o,c as d,d as i}from"./chunks/error-05.D7FyJuqe.js";import{_ as a,o as n,c as l,a3 as s}from"./chunks/framework.D1iekJsc.js";const v=JSON.parse('{"title":"エラーコード排錯","description":"MiniTavern 測連・チャット失敗時のエラーコード対照：invalidApiKey、rateLimit、visionUnsupported など。","frontmatter":{"title":"エラーコード排錯","description":"MiniTavern 測連・チャット失敗時のエラーコード対照：invalidApiKey、rateLimit、visionUnsupported など。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"エラーコード排錯 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 測連・チャット失敗時のエラーコード対照：invalidApiKey、rateLimit、visionUnsupported など。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/manual/errors"}]]},"headers":[],"relativePath":"ja/manual/errors.md","filePath":"ja/manual/errors.md","lastUpdated":1787816217000}'),c={name:"ja/manual/errors.md"};function u(h,t,p,g,m,f){return n(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="エラーコード排錯" tabindex="-1">エラーコード排錯 <a class="header-anchor" href="#エラーコード排錯" aria-label="Permalink to &quot;エラーコード排錯&quot;">​</a></h1><p>測連失敗またはチャット吹き出しのエラー時、<strong>詳細を見る</strong>をタップし、本ページの<strong>エラーコード</strong>（または文案キーワード）と照合してください。</p><p>詳細には通常次が含まれます：</p><ul><li><strong>エラーコード</strong>（英語識別子、例 <code>invalidApiKey</code>）</li><li><strong>エラー原因</strong></li><li><strong>試す修復</strong></li></ul><p>以下の「コード」は App のエラー詳細に表示される名称に準拠します。</p><hr><h2 id="クイック対照表" tabindex="-1">クイック対照表 <a class="header-anchor" href="#クイック対照表" aria-label="Permalink to &quot;クイック対照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>エラーコード</th><th>ユーザー向け要約</th><th>優先対処</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>先に API キーを記入</td><td>モデル接続に鍵を記入</td></tr><tr><td><code>invalidApiKey</code></td><td>鍵が無効または期限切れ</td><td>コピー漏れを確認；コンソールで再生成</td></tr><tr><td><code>forbidden</code></td><td>アクセス拒否</td><td>権限、モデルが開通済みか</td></tr><tr><td><code>regionForbidden</code></td><td>地域で利用不可</td><td>ネットワーク／プロキシ／国際サイトを変更</td></tr><tr><td><code>network</code></td><td>ネットワーク接続失敗</td><td>ネットワーク、Base URL、ファイアウォール</td></tr><tr><td><code>timeout</code></td><td>リクエストタイムアウト</td><td>ネットワーク；ローカルモデルはタイムアウトを延ばす</td></tr><tr><td><code>modelNotFound</code></td><td>モデルが存在しない</td><td>モデル ID を照合</td></tr><tr><td><code>modelRetired</code></td><td>モデルが下線／廃止</td><td>一覧から現在使えるモデルへ</td></tr><tr><td><code>rateLimit</code></td><td>送信が頻繁すぎる</td><td>待ってから再試行</td></tr><tr><td><code>freeTierQuota</code></td><td>無料枠のリクエスト枠</td><td>Please retry in … に従い待機；頻度を下げるか有料へ</td></tr><tr><td><code>insufficientQuota</code></td><td>枠不足</td><td>チャージ／鍵を変更</td></tr><tr><td><code>spendingCapExceeded</code></td><td>月次消費上限</td><td>コンソールで spend cap を上げる</td></tr><tr><td><code>providerReturnedError</code></td><td>上流がエラーを返した</td><td>モデル変更／同ベンダー <code>:free</code> を避ける／OpenRouter BYOK</td></tr><tr><td><code>contextLengthExceeded</code></td><td>コンテキスト超過</td><td>記憶を短縮；返信トークンを None；大コンテキストモデルへ</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude に max_tokens 不足</td><td>モデル設定で「返信トークン」をオン</td></tr><tr><td><code>badRequest</code></td><td>パラメータ誤り</td><td>パラメータと互換インタフェース形式を確認</td></tr><tr><td><code>serverError</code></td><td>サーバー側エラー</td><td>後で再試行</td></tr><tr><td><code>requestFailed</code></td><td>リクエスト失敗</td><td>詳細の原文を確認</td></tr><tr><td><code>contentPolicy</code></td><td>安全審査未通過</td><td>再生成／モデル変更／書き換え</td></tr><tr><td><code>emptyContent</code></td><td>返信が空</td><td>再試行；思考モデルのフィールドを確認</td></tr><tr><td><code>modelAtCapacity</code></td><td>モデルが満載</td><td>待機またはモデル変更</td></tr><tr><td><code>productNotActivated</code></td><td>製品未開通</td><td>コンソールでモデルを開通</td></tr><tr><td><code>visionUnsupported</code></td><td>画像非対応</td><td>視覚モデルへ、または添付をオフ</td></tr><tr><td><code>textOutputUnsupported</code></td><td>文字対話非対応</td><td>テキストチャットモデルへ；TTS／画像専用 ID を選ばない</td></tr></tbody></table><hr><h2 id="分類の詳解" tabindex="-1">分類の詳解 <a class="header-anchor" href="#分類の詳解" aria-label="Permalink to &quot;分類の詳解&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>現象</strong>：鍵未記入でリクエスト不可。</li><li><strong>対処</strong>：設定 → モデル接続 → API キーを記入。ローカル Ollama などは非空検証ならプレースホルダで可。</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>現象</strong>：401 系、鍵無効。</li><li><strong>対処</strong>：空白なしで完全コピー；国内／国際サイトと鍵の対応を確認；鍵を再生成。</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>現象</strong>：403、地域制限。</li><li><strong>対処</strong>：モデル権限を確認；プロキシまたは国際サイトの Base URL へ。</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>現象</strong>：つながらない、または長時間無応答。</li><li><strong>対処</strong>： <ul><li>Base URL を確認（ローカルでスマホの <code>localhost</code> は不可、PC の LAN IP を使う）。</li><li>PC ファイアウォールでポート開放；スマホと PC を同一 Wi‑Fi。</li><li>弱網または遅いローカルモデル：タイムアウト延長、小モデルへ。</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>現象</strong>：モデル ID 誤り。</li><li><strong>対処</strong>：測連後に一覧から再選択；ローカルは <code>ollama list</code>／LM Studio 表示名と一致。</li></ul><h3 id="modelretired" tabindex="-1">modelRetired <a class="header-anchor" href="#modelretired" aria-label="Permalink to &quot;modelRetired&quot;">​</a></h3><ul><li><strong>現象</strong>：HTTP 404、文案に <code>no longer available to new users</code> / <code>use a newer model</code>（例 <code>models/gemini-2.5-flash-lite</code>）。</li><li><strong>区別</strong>：プロバイダが廃止／新規非公開にしたモデルで、綴りミスではない。</li><li><strong>対処</strong>：モデル接続で最新一覧を取得し、稼働中の Gemini（例 <code>gemini-flash-latest</code>）へ。Interactions API への切替は不要。一覧：<a href="https://ai.google.dev/gemini-api/docs/models" target="_blank" rel="noreferrer">Gemini models</a>。</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>対処</strong>：送信頻度を下げる；後で再試行；プランを上げる。</li></ul><h3 id="freetierquota" tabindex="-1">freeTierQuota <a class="header-anchor" href="#freetierquota" aria-label="Permalink to &quot;freeTierQuota&quot;">​</a></h3><ul><li><strong>現象</strong>：Gemini などが <code>HTTP 429</code> + <code>generate_content_free_tier_requests</code>（よく limit: 20）と <code>Please retry in …s</code>。</li><li><strong>区別</strong>：<strong>無料枠の毎分／毎日リクエスト回数</strong>であり、残高ゼロでもプロジェクト月次 spend cap でもない。</li><li><strong>対処</strong>：提示秒数待って再試行；頻度を下げる；<a href="https://ai.dev/rate-limit" target="_blank" rel="noreferrer">AI Studio 用量</a> を確認；より高い枠が必要なら課金／有料へ。<a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a>。</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>区別</strong>：枠使い切り vs <strong>プロジェクト月次消費上限</strong>（後者は「後で再試行」だけではだいたい無効）。</li><li><strong>対処</strong>：チャージ；またはコンソールで spend cap を調整（例 Google AI Studio Spend ページ）。</li></ul><h3 id="providerreturnederror" tabindex="-1">providerReturnedError <a class="header-anchor" href="#providerreturnederror" aria-label="Permalink to &quot;providerReturnedError&quot;">​</a></h3><ul><li><strong>現象</strong>：OpenRouter などが <code>HTTP 429: Provider returned error</code>（<code>:free</code> でよくある）。</li><li><strong>対処</strong>：後で再試行；他ベンダーの空きモデルへ；または <a href="https://openrouter.ai/settings/integrations" target="_blank" rel="noreferrer">OpenRouter BYOK</a>。</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>対処</strong>：設定 → モデル設定 → 記憶の長さを短縮；「返信トークン」を None（適用時）；より大きいコンテキストのモデルへ。</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>対処</strong>：Claude は max_tokens 必須 → モデル設定で「返信トークン」をオンし、None にしない。</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>対処</strong>：temperature などのパラメータを確認；第三者互換が本当に OpenAI/Anthropic 形式か。</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>対処</strong>：後で再試行；エンドポイントまたはモデルを変更；続く場合はサービス事業者に詳細原文を添えて連絡。</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>対処</strong>：再生成、書き換え、審査の緩いモデルへ；一部 NSFW カードは出力遮断を招きやすい。</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>対処</strong>：再試行；一部思考モデルは reasoning のみ返す → 詳細の完全フィールドを見るかモデル変更。</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>対処</strong>：クラウドコンソールで該当製品／モデルを開通してから、現在の鍵で使う。</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>対処</strong>：視覚対応モデルへ；または画像を送らない／画像認識描写フローで純テキスト描写へ。</li></ul><h3 id="textoutputunsupported" tabindex="-1">textOutputUnsupported <a class="header-anchor" href="#textoutputunsupported" aria-label="Permalink to &quot;textOutputUnsupported&quot;">​</a></h3><ul><li><strong>現象</strong>：HTTP 400、文案に <code>response modalities</code> かつ <code>TEXT</code> 非対応（例 <code>models/gemini-2.5-flash-preview-tts</code> は <code>AUDIO</code> のみ）。</li><li><strong>区別</strong>：音声合成／画像など専用モデルでチャット測連したのであり、鍵やサンプリングの誤りではない。</li><li><strong>対処</strong>：モデル接続でテキストチャットモデル（例 <code>gemini-flash-latest</code>）へ。名称に <code>tts</code>、<code>image</code> が付く専用 ID を選ばない。音声・画像は対応機能で設定。</li></ul><hr><h2 id="ローカルモデル向け" tabindex="-1">ローカルモデル向け <a class="header-anchor" href="#ローカルモデル向け" aria-label="Permalink to &quot;ローカルモデル向け&quot;">​</a></h2><p>PC 上の Ollama / LM Studio につながらない：<a href="/ultra_guides/ja/troubleshoot">ローカルモデル排錯</a>。</p><p>App の測連／チャット報錯（エラーコード含む）：<a href="/ultra_guides/ja/manual/errors">マニュアル · エラーコード排錯</a>。</p><div class="tip custom-block"><p class="custom-block-title">スクリーンショット</p><div class="shot-flow"><figure class="shot-step"><img src="'+e+'" alt="吹き出しエラー"><figcaption>1 · 吹き出しエラー</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="詳細を見る"><figcaption>2 · 詳細を見る</figcaption></figure><figure class="shot-step"><img src="'+o+'" alt="エラー詳細"><figcaption>3 · コードと原因</figcaption></figure><figure class="shot-step"><img src="'+d+'" alt="修復の試行"><figcaption>4 · 修復のヒント</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="本ページ照合"><figcaption>5 · 本ページで照合</figcaption></figure></div></div>',53)])])}const x=a(c,[["render",u]]);export{v as __pageData,x as default};
